// MineBench - choo-choo train (classic steam locomotive, polished)
var cx=128, cz=128, ly=0;

// ---- helpers ----
function box(x1,y1,z1,x2,y2,z2,t){
  var a1=Math.min(x1,x2),b1=Math.min(y1,y2),c1=Math.min(z1,z2);
  var a2=Math.max(x1,x2),b2=Math.max(y1,y2),c2=Math.max(z1,z2);
  for(var a=a1;a<=a2;a++)for(var b=b1;b<=b2;b++)for(var c=c1;c<=c2;c++)block(a,b,c,t);
}

// y-axis cylinder
function cyl(cx,cz,rOuter,edgeThick,y0,y1,type){
  for(var x=cx-rOuter;x<=cx+rOuter;x++)
    for(var z=cz-rOuter;z<=cz+rOuter;z++){
      var d2=(x-cx)*(x-cx)+(z-cz)*(z-cz);
      var rO=Math.sqrt(d2);
      if(rO>rOuter)continue;
      for(var y=y0;y<=y1;y++)block(x,y,z,type);
    }
}

// Horizontal boiler: axis along x
function cylX(cy,cz,rOuter,x0,x1,type){
  for(var x=x0;x<=x1;x++)
    for(var y=cy-rOuter;y<=cy+rOuter;y++)
      for(var z=cz-rOuter;z<=cz+rOuter;z++){
        var d2=(y-cy)*(y-cy)+(z-cz)*(z-cz);
        if(d2>(rOuter+0.3)*(rOuter+0.3))continue;
        block(x,y,z,type);
      }
}

// Upright wheel: disc in x-y plane, thickness along z
function wheel(wx,wy,wz,r,w,type){
  for(var dz=0;dz<w;dz++)
    for(var a=-r;a<=r;a++)
      for(var b=-r;b<=r;b++){
        if(a*a+b*b>r*r+r)continue;
        block(wx+a,wy+b,wz+dz,type);
      }
}

